def human_file_size(num_bytes: int) -> str:
    size = float(num_bytes)
    for unit in ('B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'):
        if abs(size) < 1024.0 or unit == 'PiB':
            if unit == 'B':
                return f'{int(size)} {unit}'
            return f'{size:.2f} {unit}'
        size /= 1024.0

# Example:
print(human_file_size(0))        # 0 B
print(human_file_size(1536))     # 1.50 KiB
print(human_file_size(536870912))  # 512.00 MiB

languages.javascript:
function humanFileSize(numBytes) {
    const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'];
    let size = Math.abs(numBytes);
    let i = 0;
    while (size >= 1024 && i < units.length - 1) {
        size /= 1024;
        i++;
    }
    return `${numBytes < 0 ? '-' : ''}${i === 0 ? size : size.toFixed(2)} ${units[i]}`;
}

console.log(humanFileSize(1536));        // 1.50 KiB
console.log(humanFileSize(536870912));   // 512.00 MiB

