def second_largest(numbers: list) -> float:
    if len(numbers) < 2:
        raise ValueError('need at least two numbers')
    return sorted(numbers)[-2]

# Without sorting (two passes):
def second_largest_linear(numbers: list) -> float:
    if len(numbers) < 2:
        raise ValueError('need at least two numbers')
    largest = max(numbers)
    return max(n for n in numbers if n != largest)

# Examples:
print(second_largest([3, 7, 2, 9, 5]))        # 7
print(second_largest_linear([3, 7, 2, 9, 5]))  # 7

