package main

func FindDuplicates(items []int) []int {
    seen := map[int]bool{}
    dupes := map[int]bool{}
    out := []int{}
    for _, v := range items {
        if seen[v] && !dupes[v] {
            dupes[v] = true
            out = append(out, v)
        }
        seen[v] = true
    }
    return out
}

