use std::collections::HashSet;

pub fn find_duplicates(items: &[i32]) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut dupes = HashSet::new();
    let mut out = Vec::new();
    for &v in items {
        if seen.contains(&v) && dupes.insert(v) {
            out.push(v);
        }
        seen.insert(v);
    }
    out
}

