ONES = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven',
        'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen',
        'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen']
TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy',
        'eighty', 'ninety']
SCALES = ['', 'thousand', 'million', 'billion']

def _under_1000(n: int) -> str:
    out = []
    if n >= 100:
        out.append(f'{ONES[n // 100]} hundred')
        n %= 100
    if n >= 20:
        out.append(TENS[n // 10])
        n %= 10
        if n:
            out[-1] += '-' + ONES[n]
    elif n:
        out.append(ONES[n])
    return ' '.join(out)

def number_to_words(n: int) -> str:
    if n == 0:
        return 'zero'
    if n < 0:
        return 'minus ' + number_to_words(-n)
    parts = []
    scale = 0
    while n:
        chunk = n % 1000
        if chunk:
            head = _under_1000(chunk)
            parts.append(f'{head} {SCALES[scale]}'.strip())
        n //= 1000
        scale += 1
    return ' '.join(reversed(parts)).strip()

# Examples:
print(number_to_words(1234))        # one thousand two hundred thirty-four
print(number_to_words(1_000_001))   # one million one

def calculator():
    """Simple REPL calculator: 3 + 4, 10 / 2, quit to exit."""
    ops = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b if b else float('inf'),
    }
    print('Simple calculator — type "3 + 4", "quit" to exit')
    while True:
        line = input('> ').strip()
        if line.lower() in ('quit', 'exit', 'q'):
            break
        parts = line.split()
        if len(parts) != 3 or parts[1] not in ops:
            print('usage: <num> <op> <num>')
            continue
        try:
            a, b = float(parts[0]), float(parts[2])
        except ValueError:
            print('numbers only')
            continue
        print(ops[parts[1]](a, b))

if __name__ == '__main__':
    calculator()

