def tic_tac_toe():
    board = [' '] * 9
    wins = [(0, 1, 2), (3, 4, 5), (6, 7, 8),
            (0, 3, 6), (1, 4, 7), (2, 5, 8),
            (0, 4, 8), (2, 4, 6)]

    def show():
        for row in range(3):
            print(' | '.join(board[row*3:row*3+3]))
            if row < 2:
                print('-' * 9)

    def winner():
        for a, b, c in wins:
            if board[a] != ' ' and board[a] == board[b] == board[c]:
                return board[a]
        return None

    player = 'X'
    for turn in range(9):
        show()
        move = input(f'Player {player} (1-9): ')
        try:
            i = int(move) - 1
        except ValueError:
            print('enter 1-9')
            continue
        if i < 0 or i > 8 or board[i] != ' ':
            print('invalid move')
            continue
        board[i] = player
        if winner():
            show()
            print(f'Player {player} wins!')
            return
        player = 'O' if player == 'X' else 'X'
    show()
    print('Draw!')

if __name__ == '__main__':
    tic_tac_toe()

