// Node.js: follow a file like tail -f
const fs = require('fs');

function tailLog(filename, interval = 500) {
    // Poll the file size and read newly appended bytes:
    let pos = fs.statSync(filename).size;
    setInterval(() => {
        const size = fs.statSync(filename).size;
        if (size > pos) {
            const fd = fs.openSync(filename, 'r');
            const buf = Buffer.alloc(size - pos);
            fs.readSync(fd, buf, 0, buf.length, pos);
            fs.closeSync(fd);
            process.stdout.write(buf.toString());
            pos = size;
        }
    }, interval);
}

