def quicksort(items: list) -> list:
    """Return a new sorted list (readable, not in-place)."""
    if len(items) <= 1:
        return items
    pivot = items[len(items) // 2]
    left = [x for x in items if x < pivot]
    mid = [x for x in items if x == pivot]
    right = [x for x in items if x > pivot]
    return quicksort(left) + mid + quicksort(right)

# In-place Lomuto partition:
def quicksort_inplace(items, lo=0, hi=None):
    if hi is None:
        hi = len(items) - 1
    if lo >= hi:
        return
    pivot = items[hi]
    i = lo
    for j in range(lo, hi):
        if items[j] <= pivot:
            items[i], items[j] = items[j], items[i]
            i += 1
    items[i], items[hi] = items[hi], items[i]
    quicksort_inplace(items, lo, i - 1)
    quicksort_inplace(items, i + 1, hi)

