package main

func Quicksort(items []int) []int {
    if len(items) <= 1 {
        return items
    }
    pivot := items[len(items)/2]
    var left, mid, right []int
    for _, v := range items {
        switch {
        case v < pivot:
            left = append(left, v)
        case v == pivot:
            mid = append(mid, v)
        default:
            right = append(right, v)
        }
    }
    return append(append(Quicksort(left), mid...), Quicksort(right)...)
}

