pub fn quicksort<T: Ord + Clone>(items: &[T]) -> Vec<T> {
    if items.len() <= 1 {
        return items.to_vec();
    }
    let pivot = &items[items.len() / 2];
    let mut left = Vec::new();
    let mut mid = Vec::new();
    let mut right = Vec::new();
    for v in items {
        match v.cmp(pivot) {
            std::cmp::Ordering::Less => left.push(v.clone()),
            std::cmp::Ordering::Equal => mid.push(v.clone()),
            std::cmp::Ordering::Greater => right.push(v.clone()),
        }
    }
    let mut out = quicksort(&left);
    out.append(&mut mid);
    out.append(&mut quicksort(&right));
    out
}

