    size_t mid = items.size() / 2;
    auto left = mergeSort(std::vector<T>(items.begin(), items.begin() + mid));
    auto right = mergeSort(std::vector<T>(items.begin() + mid, items.end()));
    std::vector<T> out;
    size_t i = 0, j = 0;
    while (i < left.size() && j < right.size()) {
        if (left[i] <= right[j]) out.push_back(left[i++]);
        else out.push_back(right[j++]);
    }
    out.insert(out.end(), left.begin() + i, left.end());
    out.insert(out.end(), right.begin() + j, right.end());
    return out;
}

