public static List<T> MergeSort<T>(List<T> items) where T : IComparable<T>
{
    if (items.Count <= 1) return items;
    int mid = items.Count / 2;
    var left = MergeSort(items.GetRange(0, mid));
    var right = MergeSort(items.GetRange(mid, items.Count - mid));
    var out = new List<T>();
    int i = 0, j = 0;
    while (i < left.Count && j < right.Count)
        out.Add(left[i].CompareTo(right[j]) <= 0 ? left[i++] : right[j++]);
    while (i < left.Count) out.Add(left[i++]);
    while (j < right.Count) out.Add(right[j++]);
    return out;
}

