func SlidingWindowMax(nums []int, k int) []int {
    dq := []int{}   // indices with decreasing values
    out := []int{}
    for i, n := range nums {
        for len(dq) > 0 && nums[dq[len(dq)-1]] <= n {
            dq = dq[:len(dq)-1]
        }
        dq = append(dq, i)
        if dq[0] <= i-k {
            dq = dq[1:]
        }
        if i >= k-1 {
            out = append(out, nums[dq[0]])
        }
    }
    return out
