use std::collections::VecDeque;

pub fn sliding_window_max(nums: &[i32], k: usize) -> Vec<i32> {
    let mut dq: VecDeque<usize> = VecDeque::new();
    let mut out = Vec::new();
    for i in 0..nums.len() {
        while let Some(&last) = dq.back() {
            if nums[last] <= nums[i] { dq.pop_back(); } else { break; }
        }
        dq.push_back(i);
        if dq[0] <= i.saturating_sub(k) { dq.pop_front(); }
        if i + 1 >= k { out.push(nums[dq[0]]); }
    }
    out
}

