import hashlib


class BloomFilter:
    def __init__(self, size: int = 1024, num_hashes: int = 3):
        self.size = size
        self.num_hashes = num_hashes
        self.bits = bytearray(size)

    def _hashes(self, item: str):
        out = []
        for i in range(self.num_hashes):
            digest = hashlib.sha256(f'{i}:{item}'.encode()).digest()
            out.append(int.from_bytes(digest[:4], 'big') % self.size)
        return out

    def add(self, item: str) -> None:
        for h in self._hashes(item):
            self.bits[h] = 1

    def __contains__(self, item: str) -> bool:
        return all(self.bits[h] for h in self._hashes(item))

# Example:
bf = BloomFilter()
bf.add('apple')
print('apple' in bf)      # True (maybe)
print('banana' in bf)     # False (definitely not)

