// Node.js crypto for stable hashes:
const crypto = require('crypto');

class BloomFilter {
    constructor(size = 1024, numHashes = 3) {
        this.size = size;
        this.numHashes = numHashes;
        this.bits = new Uint8Array(size);
    }

    _hashes(item) {
        const out = [];
        for (let i = 0; i < this.numHashes; i++) {
            const digest = crypto.createHash('sha256')
                .update(`${i}:${item}`).digest();
            out.push(digest.readUInt32BE(0) % this.size);
        }
        return out;
    }

    add(item) {
        for (const h of this._hashes(item)) this.bits[h] = 1;
    }

    has(item) {
        return this._hashes(item).every(h => this.bits[h] === 1);
    }
}

